import { describe, it, expect } from "vitest";
import { createFreeCamera, enableOrthographicCamera } from "@babylonjs/lite";
import { labelPosition } from "./label-position.ts";

const canvas = { width: 800, height: 600, clientWidth: 400, clientHeight: 300 } as unknown as HTMLCanvasElement;

describe("labelPosition scratch", () => {
    it("perspective", () => {
        const cam = createFreeCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        const log = (name: string, p: any) => console.log(name, JSON.stringify(labelPosition(cam, canvas, p)), "far", cam.farPlane, "fov", cam.fov, "near", cam.nearPlane);
        log("center", { x: 0, y: 0, z: 0 });
        log("behind", { x: 0, y: 0, z: -20 });
        log("beyondFar", { x: 0, y: 0, z: cam.farPlane * 2 });
        log("right-out", { x: 1000, y: 0, z: 0 });
        log("up-in", { x: 0, y: 0.5, z: 0 });
        log("corner-ish", { x: 1, y: 1, z: 0 });
        expect(labelPosition(cam, canvas, { x: 0, y: 0, z: 0 }).visible).toBe(true);
        expect(labelPosition(cam, canvas, { x: 0, y: 0, z: -20 }).visible).toBe(false);
        expect(labelPosition(cam, canvas, { x: 0, y: 0, z: cam.farPlane * 2 }).visible).toBe(true);
        expect(labelPosition(cam, canvas, { x: 1000, y: 0, z: 0 }).visible).toBe(false);
        // FO check: same relative geometry, far from origin
        cam.position.x = 0;
    });
    it("floating origin matches", () => {
        const cam = createFreeCamera({ x: 50000, y: 0, z: 50000 }, { x: 50000, y: 0, z: 50010 });
        const a = labelPosition(cam, canvas, { x: 50000, y: 0, z: 50000 + 10 });
        (cam as any)._useFloatingOrigin = true;
        const b = labelPosition(cam, canvas, { x: 50000, y: 0, z: 50000 + 10 });
        console.log("FO", JSON.stringify(a), JSON.stringify(b));
        expect(b.visible).toBe(true);
        expect(Math.abs(a.x - b.x)).toBeLessThan(1e-3);
    });
    it("ortho", () => {
        const cam = createFreeCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        enableOrthographicCamera(cam);
        console.log("ortho center", JSON.stringify(labelPosition(cam, canvas, { x: 0, y: 0, z: 0 })), "behind", JSON.stringify(labelPosition(cam, canvas, { x: 0, y: 0, z: -20 })));
    });
});
